-- Earth and Space Science final module. Run seed_ess_course.sql first. Safe to run more than once.

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'earth-space-science';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 7, $j$Final Assessment: Earth and Space Science Investigation Report$j$, $j${"prompt": "Complete a safe investigation and write a report of at least 600 words. Ask a parent, guardian or teacher for permission and supervision before you begin. Use only everyday household items and public weather data. Do not use open flames, unknown chemicals or anything that could cause harm, and never look directly at the Sun. Choose one question: (a) How does the Moon's appearance change over at least 10 evenings, and what pattern do you find? (b) How do temperature, air pressure and cloud cover change over 10 days, using your own thermometer and readings from a public weather service? (c) How does the steepness of a slope change the erosion of sand or soil in a tray when you pour the same amount of water on it? (d) How hard are five household minerals or rocks when tested with a fingernail, a copper penny and a steel nail, and how do they rank? Write complete sentences, show every calculation and label each part. Proverbs 25:2 says, It is the glory of God to conceal a thing: but the honour of kings is to search out a matter.\n\nPart 1: The Question and Hypothesis. State your question and your hypothesis, and explain the earth science that led to your prediction.\nPart 2: Plan and Safety. List your materials, your independent variable, dependent variable and at least three controls. List the safety rules you followed and how an adult supervised.\nPart 3: Procedure. Describe your steps clearly enough that another student could repeat them.\nPart 4: Data. Present at least 8 observations or measurements in a table with units or descriptions, and make a graph, chart or labeled sketch.\nPart 5: Calculations and Patterns. Show at least two calculations, such as averages, ranges, rates or percent change, and describe the pattern you found.\nPart 6: Analysis. Tell what your data show, name the earth science principles involved (such as Moon phases, weather and air pressure, erosion and deposition, or mineral hardness), and compare your result with your hypothesis.\nPart 7: Sources of Error. Describe at least three sources of error and how you could improve the test.\nPart 8: Faith and Application. Explain how Psalm 19:1 and Genesis 2:15 guide honest, careful science and good stewardship of the earth, and describe how you could use earth science in a future calling.", "rubric": "100 points. Part 1, question and hypothesis: 10 points. Part 2, plan and safety: 15 points. Part 3, procedure: 10 points. Part 4, data: 15 points. Part 5, calculations and patterns: 15 points. Part 6, analysis: 15 points. Part 7, sources of error: 5 points. Part 8, faith and application: 10 points. Grammar, conventions and respectful tone: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: Earth and Space Science Investigation Report$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 31, $j$Final Exam: Earth and Space Science$j$, $j${"questions": [{"q": "The seasons are caused mainly by:", "options": ["Earth's rotation speed", "The Moon's phases", "The tilt of Earth's axis", "Earth's changing distance from the Sun"]}, {"q": "Spring tides, the highest and lowest tides, occur at:", "options": ["The quarter moons", "Only at noon", "New moon and full moon", "Only during solstices"]}, {"q": "One astronomical unit is about:", "options": ["1 million kilometers", "150 million kilometers", "9.5 trillion kilometers", "384,000 kilometers"]}, {"q": "A star like the Sun makes energy by:", "options": ["Nuclear fusion of hydrogen into helium", "Radioactive decay of lead", "Burning oxygen", "Reflecting starlight"]}, {"q": "S waves do not travel through Earth's outer core, which shows that it is:", "options": ["Made of rock", "Solid", "Liquid", "A vacuum"]}, {"q": "Where plates move apart and new crust forms, the boundary is:", "options": ["Divergent", "Transform", "Convergent", "A hot spot"]}, {"q": "A rock formed when heat and pressure change limestone is:", "options": ["Granite", "Sandstone", "Basalt", "Marble"]}, {"q": "The topsoil layer that is rich in humus is the:", "options": ["C horizon", "B horizon", "A horizon", "Bedrock"]}, {"q": "A sample starts with 80 grams of a parent isotope. After three half lives, how much remains?", "options": ["5 grams", "20 grams", "10 grams", "40 grams"]}, {"q": "A sinkhole in Florida most often forms when:", "options": ["The roof of a cavity in dissolved limestone collapses", "Plates collide", "A volcano erupts", "A glacier melts"]}, {"q": "Most weather occurs in the:", "options": ["Stratosphere", "Troposphere", "Mesosphere", "Exosphere"]}, {"q": "A sea breeze during the day blows from the:", "options": ["Mountains to the plains", "Ocean toward the land", "Land toward the ocean", "North to south"]}, {"q": "A hurricane watch means hurricane conditions are:", "options": ["Already over", "Impossible", "Expected within about 36 hours", "Possible within about 48 hours"]}, {"q": "Deep ocean currents are driven mainly by differences in:", "options": ["Waves", "Density", "Wind", "Moon phases"]}, {"q": "Genesis 2:15 teaches believers to treat the earth with:", "options": ["Fear and avoidance", "Faithful care, dressing and keeping it", "Ownership without limits", "Careless use"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Earth and Space Science$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,1,0,2,0,3,2,2,0,1,1,3,1,1}'::int[], array[$j$The 23.5 degree tilt changes how directly sunlight strikes each hemisphere.$j$,$j$The Sun and Moon pull together at new and full moon.$j$,$j$It is the average distance from Earth to the Sun.$j$,$j$Fusion in the core releases energy.$j$,$j$S waves cannot pass through liquids.$j$,$j$Magma rises and cools at divergent boundaries.$j$,$j$Marble is metamorphosed limestone.$j$,$j$Topsoil supports most plant roots.$j$,$j$80 halves to 40, 20 and then 10.$j$,$j$Groundwater dissolves limestone and leaves voids.$j$,$j$The troposphere holds most of the air and water vapor.$j$,$j$Land warms faster, so cooler sea air flows in.$j$,$j$A warning means conditions are expected within about 36 hours.$j$,$j$Cold, salty water is dense and sinks.$j$,$j$Dominion means careful stewardship.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Earth and Space Science$j$ on conflict (item_id) do nothing;
end
$seed$;
